2807	// corruptDelegationsState 构造一份含“bob 委托给 alice”的合法状态文件，
2808	// 再按 mutate 改写该提案的 delegations 字段，返回改写前后的字节与路径。
2809	// phase 决定提案停留在哪个生命周期：
2810	//   - "voting"：尚未投票；
2811	//   - "passed"：alice（归集 500）投赞成后已计票通过；
2812	//   - "rejected"：无人投票直接计票，未达法定人数；
2813	//   - "executed"：通过提案已执行。
2814	func corruptDelegationsState(t *testing.T, phase string, mutate func(p map[string]any)) (path string, good, bad []byte) {
2815		t.Helper()
2816		dir := t.TempDir()
2817		path = filepath.Join(dir, "treasury.json")
2818		store, err := InitTreasury(path, 1000)
2819		if err != nil {
2820			t.Fatal(err)
2821		}
2822		in := &CreateVoteInput{
2823			ID: "gip-del",
2824			Members: []VoteMember{
2825				{ID: "alice", Weight: 300},
2826				{ID: "bob", Weight: 200},
2827			},
2828			Delegations: []Delegation{{From: "bob", To: "alice"}},
2829			Quorum:      250,
2830			StartAt:     0,
2831			Deadline:    200,
2832			TimelockEnd: 300,
2833			Actions:     []string{"transfer:audits:100"},
2834		}
2835		mustCreateVote(t, store, in)
2836		switch phase {
2837		case "voting":
2838		case "passed":
2839			if _, err := store.CastVote("gip-del", "alice", true, 100); err != nil {
2840				t.Fatal(err)
2841			}
2842			if r, err := store.TallyVote("gip-del", 200); err != nil || !r.Passed {
2843				t.Fatalf("tally passed: %+v err=%v", r, err)
2844			}
2845		case "rejected":
2846			if r, err := store.TallyVote("gip-del", 200); err != nil || r.Passed {
2847				t.Fatalf("tally rejected: %+v err=%v", r, err)
2848			}
2849		case "executed":
2850			if _, err := store.CastVote("gip-del", "alice", true, 100); err != nil {
2851				t.Fatal(err)
2852			}
2853			if _, err := store.TallyVote("gip-del", 200); err != nil {
2854				t.Fatal(err)
2855			}
2856			if _, err := store.Execute("gip-del", 300); err != nil {
2857				t.Fatal(err)
2858			}
2859		default:
2860			t.Fatalf("unknown phase %q", phase)
2861		}
2862		store.Close()
2863	
2864		good, err = os.ReadFile(path)
2865		if err != nil {
2866			t.Fatal(err)
2867		}
2868		var clone map[string]any
2869		if err := json.Unmarshal(good, &clone); err != nil {
2870			t.Fatal(err)
2871		}
2872		p := clone["vote_proposals"].(map[string]any)["gip-del"].(map[string]any)
2873		mutate(p)
2874		bad, err = json.MarshalIndent(clone, "", "  ")
2875		if err != nil {
2876			t.Fatal(err)
2877		}
2878		bad = append(bad, '\n')
2879		if err := os.WriteFile(path, bad, 0o600); err != nil {
2880			t.Fatal(err)
2881		}
2882		return path, good, bad
2883	}
