52			{"no members", func(in *CreateVoteInput) { in.Members = nil }, ErrInvalidProposal},
53			{"empty member id", func(in *CreateVoteInput) { in.Members[0].ID = "" }, ErrInvalidProposal},
54			{"duplicate member", func(in *CreateVoteInput) { in.Members[1].ID = "alice" }, ErrInvalidProposal},
55			{"zero weight", func(in *CreateVoteInput) { in.Members[2].Weight = 0 }, ErrInvalidProposal},
